CREATE OR REPLACE VIEW listing_card WITH (security_invoker = true) AS SELECT l.id, l.status, l.brand_text, l.model_text, l.year, l.seats, l.transmission, l.fuel, l.price_per_day, l.province_id, l.district_id, l.is_verified, l.published_at, l.expires_at, l.owner_id, l.amenity_codes, l.search_tsv, l.ev_range_km, l.charge_policy, l.collateral_required, l.lat, l.lng, i.url_thumb as cover_thumb, i.blur_base64 as cover_blur, i.width as cover_width, i.height as cover_height FROM listings l LEFT JOIN listing_images i ON l.id = i.listing_id AND i.is_cover = true AND i.deleted_at IS NULL WHERE l.deleted_at IS NULL; 
